import { useEffect, useState } from "react";
import { getChildren, addReport } from "../api/api";

function AddReport() {
  const [children, setChildren] = useState([]);
  const [child_id, setChildId] = useState("");
  const [meal, setMeal] = useState("");
  const [sleep, setSleep] = useState("");
  const [mood, setMood] = useState("");
  const [date, setDate] = useState("");

  useEffect(() => {
    getChildren().then(res => setChildren(res));
  }, []);

  const handleSubmit = () => {
    addReport({
      child_id,
      meal,
      sleep_hours: sleep,
      mood,
      date
    }).then(() => alert("Report added"));
  };

  return (
    <div>
      <h2>Add Report</h2>

      <select onChange={e => setChildId(e.target.value)}>
        <option>Select Child</option>
        {children.map(c => (
          <option key={c.id} value={c.id}>{c.name}</option>
        ))}
      </select>

      <input placeholder="Meal" onChange={e => setMeal(e.target.value)} />
      <input placeholder="Sleep Hours" onChange={e => setSleep(e.target.value)} />
      <input placeholder="Mood" onChange={e => setMood(e.target.value)} />
      <input type="date" onChange={e => setDate(e.target.value)} />

      <button onClick={handleSubmit}>Add</button>
    </div>
  );
}

export default AddReport;
